class SlugifyTest(unittest.TestCase):
    def test_cases(self):
        for text, separator, max_length, expected in CASES:
            self.assertEqual(slugify(text, separator, max_length), expected, (text, separator, max_length))

    def test_invalid(self):
        for text, separator, max_length in INVALID:
            with self.assertRaises(ValueError):
                slugify(text, separator, max_length)
        with self.assertRaises(ValueError):
            slugify("x", "-", True)

    def test_unique(self):
        for base, taken, expected in UNIQUE:
            self.assertEqual(unique_slug(base, set(taken)), expected, (base, taken))
        self.assertEqual(unique_slug("a", {"a"}, "_"), "a_2")
        with self.assertRaises(ValueError):
            unique_slug("", set())

    def test_table(self):
        self.assertEqual(TABLE, EXPECTED_TABLE)
        self.assertEqual(len(TABLE), 190)


if __name__ == "__main__":
    unittest.main()
